.striped-container {
  display: flex;
  justify-content: center;
}

.striped-item {
  width: 100px;
  height: 100px;
  background-color: #f0f0f0;
  margin: 5px;
  animation: striped-animation 1s linear infinite;
}

@keyframes striped-animation {
  0% {
    background-position: 0 0;
  }
  100% {
    background-position: 100% 0;
  }
}

.striped-item:nth-child(odd) {
  background-image: linear-gradient(to right, #f0f0f0 50%, #e0e0e0 50%);
}

.striped-item:nth-child(even) {
  background-image: linear-gradient(to right, #e0e0e0 50%, #f0f0f0 50%);
}
```

